tugas menyusul benar","ops":[{"op":"set","path":["petugas",3,"nama"],"value":""},{"op":"set","path":["petugas",3,"menyusul"],"value":true}],"galat":[],"status":"draf"},{"nama":"petugas menyusul bukan boolean","ops":[{"op":"set","path":["petugas",0,"menyusul"],"value":"ya"}],"galat":["Petugas 1: penanda menyusul harus ya atau tidak"]},{"nama":"petugas baru bukan boolean","ops":[{"op":"set","path":["petugas",0,"baru"],"value":"ya"}],"galat":["Petugas 1: penanda baru harus ya atau tidak"]},{"nama":"petugas peran asing","ops":[{"op":"set","path":["petugas",0,"peran"],"value":"tukang"}],"galat":["Petugas 1: peran tidak dikenal"]},{"nama":"petugas tanpa peran lapangan","ops":[{"op":"set","path":["petugas",0,"peran"],"value":""}],"galat":[],"status":"draf"},{"nama":"petugas status asing","ops":[{"op":"set","path":["petugas",0,"status"],"value":"Magang"}],"galat":["Petugas 1: status harus Organik atau Mitra"]},{"nama":"petugas mitra tanpa sumber","ops":[{"op":"set","path":["petugas",1,"sumber"],"value":""}],"galat":["Petugas 2: sumber mitra wajib dipilih (kepka atau seleksi)"]},{"nama":"petugas organik dengan sumber","ops":[{"op":"set","path":["petugas",0,"sumber"],"value":"kepka"}],"galat":["Petugas 1: sumber mitra hanya untuk mitra"]},{"nama":"petugas sumber asing","ops":[{"op":"set","path":["petugas",1,"sumber"],"value":"titipan"}],"galat":["Petugas 2: sumber mitra tidak dikenal"]},{"nama":"petugas jabatan asing","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":["ketua","bos"]}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas jabatan dobel","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":["ketua","ketua"]}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas jabatan bukan daftar","ops":[{"op":"set","path":["petugas",0,"jabatan"],"value":"ketua"}],"galat":["Petugas 1: jabatan tidak dikenal"]},{"nama":"petugas nama dobel beda huruf","ops":[{"op":"set","path":["petugas",3,"nama"],"value":"  dedi kurnia "},{"op":"set","path":["petugas",2,"nama"],"value":"DEDI KURNIA"}],"galat":["Nama petugas dobel: dedi kurnia"]},{"nama":"petugas kurang satu (jumlah tidak sama)","ops":[{"op":"del","path":["petugas",3]}],"galat":[],"status":"draf"},{"nama":"petugas lebih satu (jumlah tidak sama)","ops":[{"op":"tambah","path":["petugas"],"value":{"id":"p5","nama":"Eka Sari","menyusul":false,"peran":"ppl","status":"Mitra","sumber":"kepka","baru":false,"jabatan":[]}}],"galat":[],"status":"draf"},{"nama":"petugas tim tanpa peran lapangan tambahan","ops":[{"op":"tambah","path":["petugas"],"value":{"id":"p5","nama":"Eka Sari","menyusul":false,"peran":"","status":"Organik","sumber":"","baru":false,"jabatan":["wakil"]}}],"galat":[],"status":"final"},{"nama":"tanpa kelas dan tanpa peran","ops":[{"op":"set","path":["kelas"],"value":[]},{"op":"set","path":["peran","pml","on"],"value":false},{"op":"set","path":["peran","ppl","on"],"value":false},{"op":"set","path":["petugas"],"value":[]}],"galat":[],"status":"draf"},{"nama":"tanpa kelas tetapi ada peran","ops":[{"op":"set","path":["kelas"],"value":[]}],"galat":[],"status":"final"},{"nama":"kunci kelas dan petugas tidak ada","ops":[{"op":"del","path":["kelas"]},{"op":"del","path":["petugas"]}],"galat":[],"status":"draf"}]}'::jsonb;
  base jsonb; c jsonb; o jsonb; x jsonb; p text[]; hasil text[]; harapan text[]; n int := 0; st text;
  admin bigint := 354; z bigint; ro text := '2906.BMA.001'; ia bigint; ib bigint; ic bigint; r jsonb; isi2 jsonb; l record; d record; kebelum boolean;
begin
  perform set_config('app.akun_id', '', true);
  base := vek -> 'base';

  -- ===== paritas pemeriksa isi dan status =====
  for c in select value from jsonb_array_elements(vek -> 'cases') loop
    x := base;
    for o in select value from jsonb_array_elements(c -> 'ops') loop
      p := array(select jsonb_array_elements_text(o -> 'path'));
      if o ->> 'op' = 'set' then x := jsonb_set(x, p, o -> 'value', true);
      elsif o ->> 'op' = 'del' then x := x #- p;
      elsif o ->> 'op' = 'tambah' then x := jsonb_set(x, p, (x #> p) || jsonb_build_array(o -> 'value'));
      elsif o ->> 'op' = 'ganti' then x := o -> 'value';
      end if;
    end loop;
    hasil := array(select e from unnest(keu_lanjutan_periksa(x)) e order by e);
    harapan := array(select jsonb_array_elements_text(c -> 'galat') order by 1);
    perform pg_temp.ok(hasil is not distinct from harapan, format('kasus "%s": SQL %s, harapan %s', c ->> 'nama', hasil, harapan));
    if cardinality(harapan) = 0 then
      perform pg_temp.ok(keu_lanjutan_status(x) = c ->> 'status', format('status kasus "%s": SQL %s, harapan %s', c ->> 'nama', keu_lanjutan_status(x), c ->> 'status'));
    end if;
    n := n + 1;
  end loop;
  perform pg_temp.ok(n = 71, 'semua kasus dijalankan');
  perform pg_temp.ok(keu_lanjutan_tgl('2026-02-29') is null and keu_lanjutan_tgl('2028-02-29') = date '2028-02-29' and keu_lanjutan_tgl('') is null, 'tanggal valid');

  -- ===== bahan: tiga identifikasi (A belum H-15, B sesudah H-15, C masih draf tanpa versi sah) =====
  select id into z from sigap_akun where aktif and id <> admin and not exists (select 1 from keu_penugasan t where t.akun_id = sigap_akun.id and t.dibatalkan_at is null) order by id limit 1;
  perform pg_temp.ok(z is not null, 'ada akun tanpa penugasan untuk uji');
  kebelum := current_date < date '2026-11-16';
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI lanjutan A', 'sah', 1, pg_temp.frm('UJI lanjutan A', 'Triwulan IV'), admin) returning id into ia;
  insert into keu_ident_versi(ident_id, ver, form) values (ia, 1, pg_temp.frm('UJI lanjutan A', 'Triwulan IV'));
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI lanjutan B', 'sah', 1, pg_temp.frm('UJI lanjutan B', 'Triwulan I'), admin) returning id into ib;
  insert into keu_ident_versi(ident_id, ver, form) values (ib, 1, pg_temp.frm('UJI lanjutan B', 'Triwulan I'));
  insert into keu_ident(tahun, ro_kode, nama, status, ver, form, dibuat_oleh) values (2026, ro, 'UJI lanjutan C', 'draf', 0, pg_temp.frm('UJI lanjutan C', 'Triwulan I'), admin) returning id into ic;

  -- ===== simpan: hak dan syarat =====
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, z, jsonb_build_object('p_ident', ia, 'p_isi', base)::text), '42501');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ic, 'p_isi', base)::text), '23514'); -- belum sah
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_isi', jsonb_set(base, '{petugas,0,status}', '"Magang"'))::text), '23514');
  begin
    perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', jsonb_set(base, '{petugas,0,status}', '"Magang"')));
    raise exception 'SEHARUSNYA GAGAL: isi tidak sah';
  exception when others then
    perform pg_temp.ok(sqlerrm like 'Isi lanjutan belum sah: Petugas 1: status harus Organik atau Mitra%', 'pesan galat memuat butir pertama: ' || sqlerrm);
  end;
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', 999999, 'p_isi', base)::text), '23514'); -- identifikasi tidak ada

  -- ===== simpan pertama: Draf (nama menyusul) =====
  isi2 := jsonb_set(jsonb_set(base, '{petugas,3,nama}', '""'), '{petugas,3,menyusul}', 'true');
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', isi2)) #> '{}';
  perform pg_temp.ok((r ->> 'ver')::int = 1 and r ->> 'status' = 'draf' and (r ->> 'berubah')::boolean, 'versi 1 Draf');
  perform pg_temp.ok((r ->> 'pasca_h15')::boolean = not kebelum, 'penanda sesudah H-15 sesuai tanggal');
  select * into l from keu_v_ident_lanjutan where ident_id = ia;
  perform pg_temp.ok(l.ver = 1 and l.status = 'draf' and l.ident_ver = 1 and l.ident_ver_sekarang = 1 and l.kebijakan_id is null, 'baris lanjutan');
  perform pg_temp.ok((select count(*) = 1 from keu_v_ident_lanjutan_versi where ident_id = ia), 'satu salinan versi');
  perform pg_temp.ok((select count(*) = 4 and count(*) filter (where menyusul) = 1 from keu_v_ident_petugas where ident_id = ia), 'tampilan petugas: 4 baris, 1 menyusul');
  perform pg_temp.ok((select count(*) = 1 from keu_ident_riwayat where ident_id = ia and aksi = 'lanjutan'), 'riwayat tercatat');

  -- simpan isi sama: tidak membuat versi baru
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', isi2)) #> '{}';
  perform pg_temp.ok((r ->> 'ver')::int = 1 and not (r ->> 'berubah')::boolean, 'isi sama: tanpa versi baru');
  perform pg_temp.ok((select count(*) = 1 from keu_v_ident_lanjutan_versi where ident_id = ia), 'tetap satu salinan');

  -- penyunting lain
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ia, 'p_isi', base, 'p_diubah', (l.diubah_at - interval '1 minute')::text)::text), '40001');

  -- ===== nama diisi: Final =====
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', base, 'p_diubah', l.diubah_at::text)) #> '{}';
  perform pg_temp.ok((r ->> 'ver')::int = 2 and r ->> 'status' = 'final', 'versi 2 Final');
  perform pg_temp.ok((select count(*) = 2 from keu_v_ident_lanjutan_versi where ident_id = ia), 'dua salinan versi');

  -- ===== tulis langsung ditutup =====
  perform set_config('app.akun_id', admin::text, true);
  perform pg_temp.gagal(format('update keu_ident_lanjutan set status = %L where ident_id = %s', 'draf', ia), '42501');
  perform pg_temp.gagal(format('delete from keu_ident_lanjutan where ident_id = %s', ia), '42501');
  perform pg_temp.gagal(format('update keu_ident_lanjutan_versi set alasan = %L where ident_id = %s', 'x', ia), '42501');
  perform set_config('app.akun_id', '', true);

  -- ===== perubahan sesudah H-15 pada lanjutan Final: wajib beralasan =====
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', base)) #> '{}';
  perform pg_temp.ok(r ->> 'status' = 'final' and (r ->> 'pasca_h15')::boolean, 'B: Final dan sesudah H-15');
  isi2 := jsonb_set(base, '{wilayah}', '"Nagari Contoh C"');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_isi', isi2)::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_lanjutan_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_isi', isi2, 'p_alasan', 'pendek')::text), '23514');
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', isi2, 'p_alasan', 'Wilayah tugas bertambah satu nagari')) #> '{}';
  perform pg_temp.ok((r ->> 'ver')::int = 2 and (select alasan = 'Wilayah tugas bertambah satu nagari' and pasca_h15 from keu_v_ident_lanjutan_versi where ident_id = ib and ver = 2), 'alasan dan penanda tersimpan pada versi 2');
  if kebelum then
    isi2 := jsonb_set(base, '{wilayah}', '"Nagari Contoh D"');
    r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', isi2)) #> '{}';
    perform pg_temp.ok((r ->> 'ver')::int = 3 and not (r ->> 'pasca_h15')::boolean, 'A: sebelum H-15 perubahan Final tanpa alasan boleh');
  end if;

  -- ===== identifikasi direvisi: dasar usang tertandai =====
  perform set_config('app.akun_id', '', true);
  update keu_ident set ver = 2 where id = ia;
  insert into keu_ident_versi(ident_id, ver, form) values (ia, 2, pg_temp.frm('UJI lanjutan A', 'Triwulan IV'));
  perform pg_temp.ok((select ident_ver = 1 and ident_ver_sekarang = 2 from keu_v_ident_lanjutan where ident_id = ia), 'dasar usang terlihat di tampilan');
  r := keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ia, 'p_isi', (select isi from keu_v_ident_lanjutan where ident_id = ia))) #> '{}';
  perform pg_temp.ok((r ->> 'berubah')::boolean and (select ident_ver = 2 from keu_v_ident_lanjutan where ident_id = ia), 'simpan ulang memperbarui dasar tanpa mengubah isi');

  -- ===== dokumen turunan =====
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, z, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'simpan')::text), '42501');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'spanduk', 'p_kunci', 'k1', 'p_aksi', 'simpan')::text), '22023');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'hapus')::text), '22023');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ic, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'simpan')::text), '23514'); -- belum ada lanjutan
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'simpan', 'p_ttd_akun', z)::text), '23514'); -- penandatangan tanpa peran
  st := keu_jalankan(admin, 'keu_ident_dokumen_simpan', jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'simpan', 'p_nomor', 'B-12/2026', 'p_tanggal', '2026-02-20', 'p_ttd_akun', admin, 'p_ttd_jabatan', 'Ketua Tim')) #>> '{}';
  perform pg_temp.ok(st = 'konsep', 'simpan = konsep');
  select * into d from keu_v_ident_dokumen where ident_id = ib and jenis = 'undangan' and kunci = 'k1';
  perform pg_temp.ok(d.nomor = 'B-12/2026' and d.status = 'konsep' and d.tanggal = date '2026-02-20' and d.ttd_nama = 'M. Iqbal Hadi, SST.', 'dokumen konsep tersimpan');
  perform set_config('app.akun_id', admin::text, true);
  perform pg_temp.gagal(format('update keu_ident_dokumen set nomor = %L where ident_id = %s', 'x', ib), '42501');
  perform set_config('app.akun_id', '', true);
  -- terbit syarat
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B', 'p_tanggal', '2026-02-20', 'p_ttd_akun', admin, 'p_ttd_jabatan', 'Ketua Tim')::text), '23514'); -- nomor pendek
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B-12/2026', 'p_ttd_akun', admin, 'p_ttd_jabatan', 'Ketua Tim')::text), '23514'); -- tanpa tanggal
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B-12/2026', 'p_tanggal', '2026-02-20', 'p_ttd_jabatan', 'Ketua Tim')::text), '23514'); -- tanpa penandatangan
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B-12/2026', 'p_tanggal', '2026-02-20', 'p_ttd_akun', admin)::text), '23514'); -- tanpa jabatan
  -- lanjutan Draf tidak boleh menerbitkan
  perform set_config('app.akun_id', '', true);
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', jsonb_set(jsonb_set(isi2, '{petugas,3,nama}', '""'), '{petugas,3,menyusul}', 'true'), 'p_alasan', 'Satu petugas diganti, nama menyusul'));
  perform pg_temp.ok((select status = 'draf' from keu_v_ident_lanjutan where ident_id = ib), 'B kembali Draf');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B-12/2026', 'p_tanggal', '2026-02-20', 'p_ttd_akun', admin, 'p_ttd_jabatan', 'Ketua Tim')::text), '23514');
  perform keu_jalankan(admin, 'keu_lanjutan_simpan', jsonb_build_object('p_ident', ib, 'p_isi', base, 'p_alasan', 'Nama petugas sudah diisi lengkap'));
  st := keu_jalankan(admin, 'keu_ident_dokumen_simpan', jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'terbit', 'p_nomor', 'B-12/2026', 'p_tanggal', '2026-02-20', 'p_ttd_akun', admin, 'p_ttd_jabatan', 'Ketua Tim')) #>> '{}';
  perform pg_temp.ok(st = 'terbit', 'diterbitkan');
  select * into d from keu_v_ident_dokumen where ident_id = ib and jenis = 'undangan' and kunci = 'k1';
  perform pg_temp.ok(d.status = 'terbit' and d.terbit_at is not null and d.lanjutan_ver = (select ver from keu_v_ident_lanjutan where ident_id = ib), 'versi lanjutan tercatat pada dokumen terbit');
  -- terbit terkunci; cabut
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'simpan', 'p_nomor', 'B-99/2026')::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'cabut', 'p_catatan', 'x')::text), '23514');
  perform pg_temp.gagal(format($q$select keu_jalankan(%s, 'keu_ident_dokumen_simpan', %L::jsonb)$q$, admin, jsonb_build_object('p_ident', ib, 'p_jenis', 'pengantar', 'p_kunci', 'semua', 'p_aksi', 'cabut', 'p_catatan', 'salah nomor surat')::text), '23514'); -- belum terbit
  st := keu_jalankan(admin, 'keu_ident_dokumen_simpan', jsonb_build_object('p_ident', ib, 'p_jenis', 'undangan', 'p_kunci', 'k1', 'p_aksi', 'cabut', 'p_catatan', 'salah nomor surat')) #>> '{}';
  perform pg_temp.ok(st = 'konsep' and (select status = 'konsep' and terbit_at is null and lanjutan_ver is null from keu_v_ident_dokumen where ident_id = ib and kunci = 'k1'), 'dicabut kembali ke konsep');
  perform pg_temp.ok((select count(*) >= 2 from keu_ident_riwayat where ident_id = ib and aksi = 'dokumen'), 'terbit dan cabut tercatat di riwayat');

  -- ===== tampilan calon penandatangan =====
  perform pg_temp.ok((select count(*) > 0 from keu_v_ident_ttd where akun_id = admin and peran_kode = 'KPA') and (select count(*) = 0 from keu_v_ident_ttd where akun_id = z), 'calon penandatangan hanya pemegang peran');
  raise notice 'LULUS 51';
end $$;
rollback;
